"""Derive SkyyShards/build_skyyshards_0.4.29.py from the GENERATED SkyyShards 0.4.28 (build_skyyshards_0.4.28.py = the tools/deploy_set.py SET
pin, made by tools/shards_0_4_28_patch.py - edit the patch, never the generated file). Every anchor is asserted once; at the end every change
is undone on a copy and compared with 0.4.28 (tools/soundpass_gen.Patch). Line endings kept.
Run:   python tools/shards_0_4_29_patch.py   then   python SkyyShards/build_skyyshards_0.4.29.py   (never --deploy)
Check: python SkyyShards/test_skyyshards_0.4.29.py

0.4.29 (2026-11-22) = SHARD CLICKER FOLLOW-UPS (round shardfix2; Skyy 2026-11-21 docs/answered/world.md "CLICKER BALANCE = SELF-SUSTAINING": "lets make
  sure we balance the clickers so everything to keep upgrading them can be gotten in the clicker, except maybe main island upgrades, and island you need
  birch to make the birch island so you have to find the tree type first kinda thing."; Skyy 2026-11-21 "build and deploy everything on your list";
  OPEN-QUESTIONS 'Shards 0.4.28' default "Foraging Island size ... Same fruit / log swap next round? [yes, next round]").
  - 1. FORAGING ISLAND SIZE PAYS LOGS, NOT SAPLINGS. Island size (isl.mat.grow "ench:4,eseed:8|ench:16,eseed:24") asked a Foraging island for its
    sapling (ESEED = the tier's sapling) since 0.4.23 / 0.4.27 - the Foraging clicker never gives one. Now the same swap as the 0.4.28 Orchard fix:
    each sapling asked = click.saplingLogs (16, NEW Server Setup row "Foraging: logs instead of a sapling") of the island's own log (ShIsl.PROD = the
    tier's first wood trunk, which its trees drop in the clicker) - Medium 128 logs, Large 384 logs + the Enchanted part as before. ShIsl.ownSeed
    now answers the "grove" style too; ShIsl.enchX returns click.saplingLogs for it (click.orchard.saplingFruit for the orchard, unchanged). A tier
    without a sapling (ESEED empty) asked none and asks none. Buying a NEW island (isl.buyItems "raw:128,seed:16") keeps its sapling - Skyy's
    "find the tree type first" exception. The page's Island size row shows the new cost with the usual have / need lines (ShPage.ckCostR reads
    ShIsl.mats; the purchase ShCore.grow pays the same mats - one source for both). An upgrade click on the Foraging page now also checks the
    page is fresh (ShPage.ckFresh: the same profile, the same island type in that slot - as the Ranching / Orchard rows since 0.4.28), so a
    profile switch with the page open buys nothing.
  - 2. RANCHING FORTUNE (survey, no code change): no Ranching Fortune stat exists anywhere in the SET, so the Ranching clicker's Fortune stays 0:
    SkyySkills 0.4.73 skill:fn:fortune (SkillFortFn.rowOf) answers Mining / Foraging / Farming only and SkyySkills has no Ranching perk row (Ranching
    XP = pickups only - no double drops in the world either); nothing writes skill:bonus dd.ranching - SkyyGear 0.3.59 GearTool.ROWKEY = mining /
    foraging / farming, SkyyAccessories 0.5.38 dd.mining / foraging / farming / fishing, SkyyPets 0.4.28 STATS fortune.mining / foraging / farming,
    SkyyTrees 0.6.10 dd.mining / foraging / farming; SkyyGear-Stat-Catalog lists Mining / Farming / Foraging Fortune only. Inventing one is Skyy's
    call (a question for the main session). The read path stays as 0.4.28 built it (skill:fn:fortune "Ranching", else the dd.ranching sum of every
    skill:bonus source), so a future source counts with no Shards change - the harness proves a dd.ranching source gives Fortune > 0.
    SkyySkills is NOT changed this round.
  NUMBERS (new, Server Setup -> Shards -> Shard clicker; editable): click.saplingLogs 16 (1 .. 10000).
  SAVED DATA: none changed (no new key, no migration). Old files load unchanged.
  ROLLBACK 0.4.29 -> 0.4.28 alone: the jar; Foraging Island size asks for saplings again; click.saplingLogs stays in config.properties as an
    unknown line (ignored). No saved-data step.
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

HERE = os.path.join(ROOT, "SkyyShards")
P = G.Patch(os.path.join(HERE, "build_skyyshards_0.4.28.py"), os.path.join(HERE, "build_skyyshards_0.4.29.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.28"\n') and P.has("GENERATED by tools/shards_0_4_28_patch.py") and P.has("public static boolean ownSeed(") and not P.has("CK_SAPL"), \
    "not the generated SkyyShards 0.4.28"
REG0, SYS0 = P.s.count("registerCommand("), P.s.count("registerSystem(")
HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.4.29 (2026-11-22)"):].rstrip() + "\n"

# ---------------------------------------------------------------------------------------------------- 0. header + version
P.rep('''"""SkyyShards 0.4.28 - build script (javassist via jpype). GENERATED by tools/shards_0_4_28_patch.py from build_skyyshards_0.4.27.py
(generated by tools/shards_0_4_27_patch.py from 0.4.26, ... back to tools/shards_0_4_patch.py from 0.3.2; edit the patch, never this file).
Changes are marked "0.4.28" /''', '''"""SkyyShards 0.4.29 - build script (javassist via jpype). GENERATED by tools/shards_0_4_29_patch.py from build_skyyshards_0.4.28.py
(generated by tools/shards_0_4_28_patch.py from 0.4.27, ... back to tools/shards_0_4_patch.py from 0.3.2; edit the patch, never this file).
Changes are marked "0.4.29" / "0.4.28" /''')
P.rep('''Run:   python SkyyShards/build_skyyshards_0.4.28.py   -> SkyyShards/SkyyShards-0.4.28.jar   (never --deploy: tools/deploy_set.py installs the set)
Check: python SkyyShards/test_skyyshards_0.4.28.py
''', '''Run:   python SkyyShards/build_skyyshards_0.4.29.py   -> SkyyShards/SkyyShards-0.4.29.jar   (never --deploy: tools/deploy_set.py installs the set)
Check: python SkyyShards/test_skyyshards_0.4.29.py
''' + NOTE)
P.rep('VERSION = "0.4.28"\n', 'VERSION = "0.4.29"\n')

# ---------------------------------------------------------------------------------------------------- 1. the setting (Server Setup -> Shards -> Shard clicker)
P.rep('''"public static volatile int OQ_SAPF = 16;",''', '''"public static volatile int OQ_SAPF = 16;", "public static volatile int CK_SAPL = 16;",''')   # 0.4.29
P.rep('''          "Orchard Island size: own fruit asked per sapling the grow row names.", "reload@config.properties:click.orchard.saplingFruit"),
''', '''          "Orchard Island size: own fruit asked per sapling the grow row names.", "reload@config.properties:click.orchard.saplingFruit"),
         ("click.saplingLogs", "Foraging: logs instead of a sapling", "clicker", "int", "16", "1", "10000", "", "", "live",   # 0.4.29
          "Foraging Island size: own logs asked per sapling the grow row names.", "reload@config.properties:click.saplingLogs"),
''')
P.rep('''          "  OQ_SAPF = intOf(p.getProperty(\\"click.orchard.saplingFruit\\"), 16, 1, 10000);",   # fix (critic): Island size pays fruit, not world saplings
''', '''          "  OQ_SAPF = intOf(p.getProperty(\\"click.orchard.saplingFruit\\"), 16, 1, 10000);",   # fix (critic): Island size pays fruit, not world saplings
          "  CK_SAPL = intOf(p.getProperty(\\"click.saplingLogs\\"), 16, 1, 10000);",   # 0.4.29: Foraging Island size pays logs, not world saplings
''')

# ---------------------------------------------------------------------------------------------------- 2. ShIsl: a Foraging island's sapling = its own logs
P.rep('''  return "orchard".equals(STYLE[kd]) && ESEED[t].length() > 0;''',
      '''  return ("orchard".equals(STYLE[kd]) || "grove".equals(STYLE[kd])) && ESEED[t].length() > 0;   // 0.4.29: + Foraging (its clicker gives no sapling either)''')
P.rep('''  if (ownSeed(kd, t, tk)) return (long) @PKG@.ShCfg.OQ_SAPF;   // fix (critic): fruit per sapling asked''',
      '''  if (ownSeed(kd, t, tk)) return (long) ("grove".equals(STYLE[kd]) ? @PKG@.ShCfg.CK_SAPL : @PKG@.ShCfg.OQ_SAPF);   // fix (critic): fruit per sapling asked; 0.4.29: logs per sapling (Foraging)''')
P.rep('''  if (ownSeed(kd, t, tk)) return PROD[t];   // fix (critic): an Orchard tree island's Island size pays its own fruit (x click.orchard.saplingFruit in mats)''',
      '''  if (ownSeed(kd, t, tk)) return PROD[t];   // fix (critic): an Orchard tree island's Island size pays its own fruit (x click.orchard.saplingFruit in mats); 0.4.29: a Foraging island its own logs (x click.saplingLogs)''')

# ---------------------------------------------------------------------------------------------------- 3. a stale Foraging page buys nothing (the ranch / orchard ckFresh)
# Island size is bought from the Foraging page now with logs: an upgrade click checks the page still shows this profile's island of that type
# (ckFresh: page key = the current profile key, the slot holds the type drawn) - as the Ranching / Orchard / Farming / town rows already do
P.rep('''    if ((kd == @PKG@.ShClk.RNK || kd == @PKG@.ShClk.ORK) && !ckFresh(k, kd, s)) return "=The page is up to date now - click Upgrade again.";   // 0.4.28: a stale ranch / orchard island''',
      '''    if ((kd == @PKG@.ShClk.RNK || kd == @PKG@.ShClk.ORK || kd == @PKG@.ShClk.FK) && !ckFresh(k, kd, s)) return "=The page is up to date now - click Upgrade again.";   // 0.4.28: a stale ranch / orchard island; 0.4.29: + a stale Foraging page''')

# ---------------------------------------------------------------------------------------------------- 4. the ready line
P.rep(r'''log("[SkyyShards] @VERSION@ ready (@KITID@) - 0.4.28:''', r'''log("[SkyyShards] @VERSION@ ready (@KITID@) - 0.4.29: Foraging Island size pays the island's own logs instead of saplings (click.saplingLogs); 0.4.28:''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0, "command / system registrations changed"
P.finish()
